#include <set>
#include <functional>
#include <iostream>

// Defines a set where 5 is greater than 1 (descending order)
typedef std::set<int, std::greater<int>> IntSetDesc;

int main() {
    IntSetDesc coll1;
    coll1.insert(4);
    coll1.insert(1);
    coll1.insert(6);

    // Output will be sorted descending: 6 4 1
    for (int x : coll1) {
        std::cout << x << ' ';
    }
    std::cout << "\n";
}
